"""Character and relationship data models for pipeline_v2."""

from __future__ import annotations

from dataclasses import dataclass, field
from typing import Any


@dataclass
class CharacterPreferences:
    """Character preferences — generated by LLM from city/culture context."""
    prefer: list[str] = field(default_factory=list)
    avoid: list[str] = field(default_factory=list)
    dietary: str = ""
    budget: str = "medium"


@dataclass
class CharacterMobility:
    """Mobility constraints, grounded to real districts from world.json."""
    home_district_id: str = ""
    home_district_name: str = ""
    work_district_id: str = ""
    work_district_name: str = ""
    lat: float = 0.0                   # current position — district center lat
    lng: float = 0.0                   # current position — district center lng
    current_place: dict[str, Any] = field(default_factory=dict)
    preferred_modes: list[str] = field(default_factory=lambda: ["TRANSIT"])
    max_walk_m: int = 800
    has_bicycle: bool = False
    has_car: bool = False


@dataclass
class CharacterAvailability:
    """Typical free time windows."""
    typical_free_windows: list[str] = field(default_factory=list)
    punctuality: str = "medium"       # high / medium / low


@dataclass
class CharacterCommunication:
    """Communication preferences."""
    style: str = ""                   # LLM-generated description
    response_latency: str = "medium"  # fast / medium / delayed
    preferred_channels: list[str] = field(default_factory=lambda: ["MessagingAppV2"])


@dataclass
class CharacterConstraint:
    """A constraint attached to a character."""
    constraint_type: str = "visible"   # "visible" | "hidden"
    content: str = ""
    reveal_trigger: str = ""           # For hidden: "after_first_plan" | "after_checkin" | "30min_before_deadline"


@dataclass
class Character:
    """A single virtual character living in the city."""
    character_id: str
    name: str
    name_romanized: str = ""
    age: int = 0
    gender: str = ""
    occupation: str = ""
    personality_traits: list[str] = field(default_factory=list)
    preferences: CharacterPreferences = field(default_factory=CharacterPreferences)
    mobility: CharacterMobility = field(default_factory=CharacterMobility)
    availability: CharacterAvailability = field(default_factory=CharacterAvailability)
    communication: CharacterCommunication = field(default_factory=CharacterCommunication)
    constraints: list[CharacterConstraint] = field(default_factory=list)
    source: str = ""                   # "llm_generated" | "demo_template"


@dataclass
class Relationship:
    """A relationship edge between two characters."""
    character_id: str                  # source
    related_id: str                    # target
    type: str = ""                     # "friend" | "coworker" | "family" | "neighbor" | ...
    subtype: str = ""                  # "同团队" | "大学同学" | "弟弟" | ...
    strength: str = "medium"           # "weak" | "medium" | "strong" | "very_strong"
    trust_level: str = "medium"        # "low" | "medium" | "high" | "very_high"
    communication_frequency: str = ""  # "daily" | "weekly" | "monthly" | "rarely"
    context: str = ""                  # LLM-generated description of the relationship


@dataclass
class RelationshipGraphEdge:
    """Simplified edge for the graph index."""
    from_id: str
    to_id: str
    type: str = ""


@dataclass
class RelationshipGraphNode:
    """Simplified node for the graph index."""
    id: str
    name: str
    type: str = "character"


@dataclass
class RelationshipGraph:
    """Indexable relationship graph for quick lookups."""
    nodes: list[RelationshipGraphNode] = field(default_factory=list)
    edges: list[RelationshipGraphEdge] = field(default_factory=list)


@dataclass
class CharacterSet:
    """Complete character generation result."""
    schema_version: str = "v2.character.v1"
    city_id: str = ""
    city_name: str = ""
    generated_at: str = ""
    generation_config: dict[str, Any] = field(default_factory=dict)
    characters: list[Character] = field(default_factory=list)
    relationships: list[Relationship] = field(default_factory=list)
    relationship_graph: RelationshipGraph = field(default_factory=RelationshipGraph)

    def to_dict(self) -> dict[str, Any]:
        from dataclasses import asdict
        return asdict(self)
